package query
import (
 "testing"
 "github.com/weiloon1234/Foundry-Go/database/codec"
 "github.com/weiloon1234/Foundry-Go/decimal"
)
var resourceValue Expression[cursorRecord,int64]
var resourceParameter RowExpression[cursorRecord,int64]
var resourceSummary NullableOrderedAggregate[cursorRecord,decimal.Decimal]
func BenchmarkResourceFieldCapabilities(b *testing.B) {
 field:=NewExactField[cursorRecord,int64]("records","id",codec.Signed[int64]())
 b.Run("value",func(b *testing.B){b.ReportAllocs();for b.Loop(){resourceValue=Value(field)}})
 b.Run("parameter",func(b *testing.B){b.ReportAllocs();for b.Loop(){resourceParameter=Param(field,int64(7))}})
 b.Run("sum",func(b *testing.B){b.ReportAllocs();for b.Loop(){resourceSummary=Sum(field)}})
}
func BenchmarkResourceMutationCompile(b *testing.B) {
 q:=mutationQuery()
 id:=NewScalarField[user,int64]("users","id",codec.Signed[int64]())
 name:=NewTextField[user,string]("users","name",codec.String[string]())
 row:=Change(Assign[user]("users","name",codec.String[string](),"owned"))
 policy:=OnConflict(name).DoUpdate(name.Incoming())
 for _,item:=range []struct{name string;compile func()(Statement,error)}{
  {"insert",func()(Statement,error){return (insertPlan[user]{query:q,rows:[]Mutation[user]{row,row}}).compile()}},
  {"upsert",func()(Statement,error){return (insertPlan[user]{query:q,rows:[]Mutation[user]{row,row},conflict:&policy}).compile()}},
  {"update",func()(Statement,error){return (mutationPlan[user]{query:q.Where(id.Eq(1)),kind:updateModel,mutation:row}).compile()}},
 } {
  b.Run(item.name,func(b *testing.B){if _,err:=item.compile();err!=nil{b.Fatal(err)};b.ReportAllocs();for b.Loop(){if _,err:=item.compile();err!=nil{b.Fatal(err)}}})
 }
}

func TestResourceCursorCompatibility(t *testing.T) {
 rank:=NewNullableOrderedField[cursorRecord,int64]("records","rank",codec.Signed[int64]())
 q:=cursorQuery().OrderBy(rank.Desc())
 plan,err:=q.cursorPlan(CursorRequest[cursorRecord]{Size:20})
 if err!=nil {t.Fatal(err)}
 token,err:=makeCursor(plan.scope,plan.fields,cursorRecord{ID:42})
 if err!=nil {t.Fatal(err)}
 statement,err:=plan.query.Compile()
 if err!=nil {t.Fatal(err)}
 t.Logf("resource cursor scope=%s token=%s sql=%s args=%v",plan.scope,token.Token(),statement.SQL(),statement.Arguments())
}

